const body = $json.body || $json;
let sender = body?.whatsappInboundMessage?.from || body?.from || '';
let message = body?.whatsappInboundMessage?.text?.body || body?.text?.body;

if (!message && body?.whatsappInboundMessage?.interactive) {
  const interact = body.whatsappInboundMessage.interactive;
  message = interact.list_reply?.id || interact.button_reply?.id || interact.list_reply?.title || interact.button_reply?.title;
}

message = message || 'Hola';
let name = body?.whatsappInboundMessage?.customerProfile?.name || 'Cliente';

return {
  sender: String(sender).trim(),
  message: String(message).trim(),
  name: String(name).trim(),
  shop_slug: 'demo'
};

// Prepare context for State Machine - combine all data
const msg = $('Extract Message').item.json;
const ctxRaw = $('Get Shop Context').item.json;
const ctx = Array.isArray(ctxRaw) ? ctxRaw[0] : ctxRaw;
const sessRaw = $('Get Session').item.json;
const sess = Array.isArray(sessRaw) ? sessRaw[0] : sessRaw;

const services = (ctx?.services || '').split(',').map(s => s.trim()).filter(Boolean);
const professionals = (ctx?.professionals || '').split(',').map(s => s.trim()).filter(Boolean);

const today = new Date();
const pad = n => String(n).padStart(2, '0');
const todayStr = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;

// Log session for debugging
console.log('Session from DB:', JSON.stringify(sess));

return {
  userMessage: msg.message,
  userName: msg.name,
  sender: msg.sender,
  shopName: ctx?.shop_name || 'Peluquería',
  services: services,
  professionals: professionals,
  currentState: sess?.current_state || 'IDLE',
  currentIntent: sess?.intent || null,
  sessionService: sess?.service || null,
  sessionProfessional: sess?.professional || null,
  sessionDate: sess?.preferred_date || null,
  sessionTime: sess?.preferred_time || null,
  todayDate: todayStr
};

// =====================================================
// STATE MACHINE v8: Fixed Session Handling
// =====================================================

const prevContext = $json;
const userMessage = prevContext.userMessage;
const msgLower = userMessage.toLowerCase();

// Session values from DB
let service = prevContext.sessionService;
let professional = prevContext.sessionProfessional;
let preferredDate = prevContext.sessionDate;
let preferredTime = prevContext.sessionTime;
let currentState = prevContext.currentState || 'IDLE';
let intent = prevContext.currentIntent;

const sender = prevContext.sender;
const userName = prevContext.userName;
const shopName = prevContext.shopName;
const services = prevContext.services;
const professionals = prevContext.professionals;

console.log('=== STATE MACHINE INPUT ===');
console.log('Message:', userMessage);
console.log('Current State:', currentState);
console.log('Service:', service);
console.log('Professional:', professional);

// =====================================================
// STEP 1: Extract data from user message
// =====================================================

// Check if message matches a service
for (const s of services) {
  const sName = s.toLowerCase().split('(')[0].trim();
  if (userMessage === s || msgLower.includes(sName)) {
    service = s;
    console.log('Extracted service:', service);
    break;
  }
}

// Check if message matches a professional
for (const p of professionals) {
  const pLower = p.toLowerCase();
  const firstName = pLower.split(' ')[0];
  if (userMessage === p || msgLower === pLower || msgLower.includes(firstName)) {
    professional = p;
    console.log('Extracted professional:', professional);
    break;
  }
}

// Check for date (YYYY-MM-DD format from list selection)
const dateMatch = userMessage.match(/^(\d{4}-\d{2}-\d{2})$/);
if (dateMatch) {
  preferredDate = dateMatch[1];
  console.log('Extracted date:', preferredDate);
}

// Check for time (HH:MM or HH:MM:SS format)
const timeMatch = userMessage.match(/^(\d{1,2}:\d{2})(:\d{2})?$/);
if (timeMatch) {
  preferredTime = timeMatch[1] + ':00';
  console.log('Extracted time:', preferredTime);
}

// =====================================================
// STEP 2: Determine intent
// =====================================================
if (currentState === 'IDLE') {
  if (msgLower.includes('reservar') || msgLower.includes('turno') || msgLower.includes('agendar') || msgLower.includes('cita')) {
    intent = 'BOOK';
  } else if (msgLower.includes('cancelar')) {
    intent = 'CANCEL';
  } else if (msgLower.includes('hola') || msgLower.includes('buenas') || msgLower.includes('buen dia')) {
    intent = 'GREET';
  } else if (msgLower.includes('si') || msgLower.includes('dale') || msgLower.includes('ok')) {
    intent = 'BOOK';
  }
} else if (currentState.startsWith('AWAITING_')) {
  // Continue booking flow
  intent = 'BOOK';
}

// =====================================================
// STEP 3: Generate next 7 days for date selection
// =====================================================
const days = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const months = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const today = new Date();
const pad = n => String(n).padStart(2, '0');

const dateOptions = [];
for (let i = 0; i < 7; i++) {
  const d = new Date(today);
  d.setDate(d.getDate() + i);
  const iso = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const dayName = i === 0 ? 'Hoy' : (i === 1 ? 'Mañana' : days[d.getDay()]);
  const label = `${dayName} ${d.getDate()} ${months[d.getMonth()]}`;
  dateOptions.push({ id: iso, title: label, description: '' });
}

// =====================================================
// STEP 4: Determine response based on what's missing
// =====================================================
let response = null;
let routeTo = 0; // 0=REPLY, 1=FETCH_TIMES, 2=BOOK_NOW, 3=CANCEL

if (intent === 'GREET') {
  response = {
    type: 'text',
    text: { body: `¡Hola! 👋 Bienvenido a *${shopName}*. ¿Querés reservar un turno?` }
  };
  currentState = 'IDLE';
  intent = null;
  // Reset booking data on greet
  service = null;
  professional = null;
  preferredDate = null;
  preferredTime = null;

} else if (intent === 'BOOK' || currentState.startsWith('AWAITING_')) {
  intent = 'BOOK';

  if (!service) {
    const rows = services.slice(0, 10).map(s => ({ id: s, title: s.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💇 Nuestros Servicios' },
        body: { text: '¿Qué servicio te gustaría? 😊' },
        footer: { text: shopName },
        action: { button: 'Ver Servicios', sections: [{ title: 'Servicios', rows: rows }] }
      }
    };
    currentState = 'AWAITING_SERVICE';

  } else if (!professional) {
    const rows = professionals.slice(0, 10).map(p => ({ id: p, title: p.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💈 Nuestros Profesionales' },
        body: { text: `Elegiste *${service}*. ¿Con quién querés?` },
        footer: { text: shopName },
        action: { button: 'Ver Profesionales', sections: [{ title: 'Profesionales', rows: rows }] }
      }
    };
    currentState = 'AWAITING_PROFESSIONAL';

  } else if (!preferredDate) {
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '📅 Elegí una Fecha' },
        body: { text: `*${service}* con *${professional}*. ¿Para qué día?` },
        footer: { text: shopName },
        action: { button: 'Ver Fechas', sections: [{ title: 'Próximos días', rows: dateOptions }] }
      }
    };
    currentState = 'AWAITING_DATE';

  } else if (!preferredTime) {
    // Need to fetch available times
    currentState = 'AWAITING_TIME';
    routeTo = 1; // FETCH_TIMES

  } else {
    // All data collected - book now
    routeTo = 2; // BOOK_NOW
  }

} else if (intent === 'CANCEL') {
  routeTo = 3; // CANCEL_FLOW

} else {
  response = {
    type: 'text',
    text: { body: `¡Hola! 👋 ¿Querés reservar un turno?\n\nDecime *reservar* para comenzar.` }
  };
  currentState = 'IDLE';
}

console.log('=== STATE MACHINE OUTPUT ===');
console.log('Route to:', routeTo);
console.log('New State:', currentState);
console.log('Service:', service);
console.log('Professional:', professional);
console.log('Date:', preferredDate);
console.log('Time:', preferredTime);

return {
  routeTo: routeTo,
  response: response,
  sender: sender,
  updateSession: {
    current_state: currentState || 'IDLE',
    intent: intent || '',
    service: service || '',
    professional: professional || '',
    preferred_date: preferredDate || '',
    preferred_time: preferredTime || ''
  },
  context: {
    sender: sender,
    userName: userName,
    shopName: shopName,
    service: service,
    professional: professional,
    preferredDate: preferredDate,
    preferredTime: preferredTime
  }
};

const slots = $json;
const context = $('Pass Data').item.json.context;
const sender = $('Pass Data').item.json.sender;
const shopName = context.shopName;
const preferredDate = context.preferredDate;

if (!slots || slots.length === 0 || slots.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `😕 No hay horarios disponibles para esa fecha. ¿Probamos otro día?` }
    }
  };
}

const rows = slots.slice(0, 10).map(slot => {
  const time = slot.start_time ? slot.start_time.substring(11, 16) : String(slot);
  return { id: time + ':00', title: time, description: '' };
});

const dateParts = preferredDate.split('-');
const formattedDate = `${dateParts[2]}/${dateParts[1]}`;

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '🕐 Horarios Disponibles' },
      body: { text: `📅 *${formattedDate}* con *${context.professional}*\n\n¿A qué hora te viene bien?` },
      footer: { text: shopName },
      action: { button: 'Ver Horarios', sections: [{ title: 'Horarios', rows: rows }] }
    }
  }
};

const result = $json;
const context = $('Pass Data').item.json.context;
const sender = $('Pass Data').item.json.sender;

if (result.success) {
  const dateParts = context.preferredDate.split('-');
  const formattedDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
  const formattedTime = context.preferredTime.substring(0, 5);

  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `✅ *¡Reserva Confirmada!*\n\n💇 *Servicio:* ${context.service}\n💈 *Profesional:* ${context.professional}\n📅 *Fecha:* ${formattedDate} a las ${formattedTime}\n\n📍 *Lugar:* ${context.shopName}\n\n¡Te esperamos! 🎉` }
    }
  };
} else {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `❌ Hubo un problema. Error: ${result.error || 'Desconocido'}\n\n¿Querés intentar con otro horario?` }
    }
  };
}

const appointments = $json;
const context = $('Pass Data').item.json.context;
const sender = $('Pass Data').item.json.sender;

if (!appointments || appointments.length === 0) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `No tenés turnos pendientes. 😊 ¿Querés reservar uno?` }
    }
  };
}

const rows = appointments.slice(0, 10).map(apt => {
  const date = apt.start_time ? apt.start_time.substring(0, 10) : '';
  const time = apt.start_time ? apt.start_time.substring(11, 16) : '';
  const dateParts = date.split('-');
  const shortDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}` : date;

  return {
    id: apt.id,
    title: `${shortDate} ${time}`.slice(0, 24),
    description: apt.service_name || 'Servicio'
  };
});

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '📋 Tus Turnos' },
      body: { text: 'Seleccioná el turno que querés cancelar:' },
      footer: { text: context.shopName },
      action: { button: 'Ver Turnos', sections: [{ title: 'Turnos', rows: rows }] }
    }
  }
};
